INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Бюджетная политика: ситуационные задачи','Регион планирует покрыть собственное расходное обязательство прямым обязательным списанием денег с муниципальных бюджетов без трансфертов. Как оценить схему?','["Она допускается при наличии регионального постановления о субсидиях","Она нарушает самостоятельность бюджетов и запрет возлагать свои обязательства на другой бюджет","Она обязательна, если расходы названы общегосударственными","Она допустима без указания бюджета-источника при дефиците"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 31','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 31 указанного нормативного акта: Она нарушает самостоятельность бюджетов и запрет возлагать свои обязательства на другой бюджет.',true),
('Бюджетная политика: ситуационные задачи','Федеральный орган предлагает изъять у региона всю экономию, полученную от сокращения неэффективных расходов. Какой принцип этому препятствует?','["Недопустимость изъятия экономии по расходам, возникшей при эффективном исполнении бюджета","Принцип обязательного перераспределения всей экономии в федеральный бюджет","Правило о возврате любых сэкономленных средств в резервный фонд субъекта","Правило об обязательном погашении дефицита другого бюджета"]'::jsonb,0,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 31','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 31 указанного нормативного акта: Недопустимость изъятия экономии по расходам, возникшей при эффективном исполнении бюджета.',true),
('Бюджетная политика: ситуационные задачи','Субъект уменьшил доходы муниципалитета изменением законодательства в середине финансового года, не компенсируя потери. Каково требование БК?','["Компенсация не требуется при любой региональной налоговой реформе","Компенсация производится исключительно после завершения трёх финансовых лет","Достаточно уведомления муниципалитета за пять дней","Изменения соответствующих бюджетов должны предусматривать компенсацию снижения доходов"]'::jsonb,3,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 31','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 31 указанного нормативного акта: Изменения соответствующих бюджетов должны предусматривать компенсацию снижения доходов.',true),
('Бюджетная политика: ситуационные задачи','Город хочет самостоятельно выбрать направления расходования собственных нецелевых бюджетных средств в пределах закона. Какой принцип это поддерживает?','["Принцип передачи всех решений по расходам губернатору","Принцип общего контроля финансовых органов без права муниципалитета","Самостоятельность бюджетов с учётом установленных ограничений","Принцип подведомственности как запрет муниципального планирования"]'::jsonb,2,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 31','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 31 указанного нормативного акта: Самостоятельность бюджетов с учётом установленных ограничений.',true),
('Бюджетная политика: ситуационные задачи','Правительство субъекта объявляет, что местная администрация не имеет обязанности обеспечивать сбалансированность своего бюджета. Что верно?','["Обязанность есть только у федерального бюджета","У местного самоуправления есть право и обязанность самостоятельно обеспечивать сбалансированность","Обязанность относится только к субъектам с бюджетным дефицитом","Обязанность возникает лишь после решения финансового органа области"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 31','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 31 указанного нормативного акта: У местного самоуправления есть право и обязанность самостоятельно обеспечивать сбалансированность.',true),
('Бюджетная политика: ситуационные задачи','Муниципалитет хочет не отражать в своём бюджете предполагаемые расходы на обслуживание долга, чтобы уменьшить формальный дефицит. Что нарушено?','["Принцип полноты отражения расходов и источников финансирования дефицита","Принцип межведомственного согласования только налоговых доходов","Правило учёта лишь капитальных расходов","Правило полного исключения долговых платежей из бюджетной отчётности"]'::jsonb,0,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 32','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 32 указанного нормативного акта: Принцип полноты отражения расходов и источников финансирования дефицита.',true),
('Бюджетная политика: ситуационные задачи','Финансовый орган решил исключить из бюджета значимую часть планируемых доходов, сохранив их на отдельной ведомственной таблице. Какое требование нарушено?','["Исключительно требование опубликовать партийную программу","Обязанность ежегодной приватизации регионального имущества","Только принцип назначения выборов по месту регистрации","Полнота отражения всех доходов бюджета"]'::jsonb,3,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 32','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 32 указанного нормативного акта: Полнота отражения всех доходов бюджета.',true),
('Бюджетная политика: ситуационные задачи','Проект бюджета предполагает расходы больше доходов, но источники финансирования дефицита вообще не предусмотрены. Как устранить нарушение сбалансированности?','["Объявить дефицит доходом при утверждении бюджета","Отразить недостающие средства как внебюджетные обещания","Соотнести расходы с доходами и законно предусмотренными источниками финансирования дефицита","Уменьшить статистическую погрешность без изменений бюджетных показателей"]'::jsonb,2,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 33','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 33 указанного нормативного акта: Соотнести расходы с доходами и законно предусмотренными источниками финансирования дефицита.',true),
('Бюджетная политика: ситуационные задачи','Департамент планирует дефицит в максимальном объёме, хотя допускается существенно меньший. Какой ориентир предписывает БК?','["Максимизировать дефицит ради увеличения расходов","Минимизировать размер дефицита при составлении, утверждении и исполнении бюджета","Не учитывать размер дефицита до закрытия финансового года","Обязательно сделать дефицит равным расходам на обслуживание долга"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 33','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 33 указанного нормативного акта: Минимизировать размер дефицита при составлении, утверждении и исполнении бюджета.',true),
('Бюджетная политика: ситуационные задачи','Регион увеличил расходы на 20 млрд без дополнительного дохода либо источников финансирования. Какое правило следует проверить первым?','["Соответствие расходов сумме доходов и допустимых источников финансирования дефицита","Обязательное повышение всех муниципальных налогов","Необходимость замены регионального закона федеральным указом","Достаточность публикации сметы в средствах массовой информации"]'::jsonb,0,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 33','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 33 указанного нормативного акта: Соответствие расходов сумме доходов и допустимых источников финансирования дефицита.',true),
('Бюджетная политика: ситуационные задачи','Министерство может достигнуть одинакового результата программы за 6 или 8 млрд при сопоставимом качестве. Какой выбор соответствует бюджетной эффективности?','["Выбрать 8 млрд, поскольку максимальные расходы свидетельствуют о полном исполнении","Разделить средства между поставщиками без оценки результата","Выбрать вариант с самым большим числом административных согласований","Выбрать достижение результата с наименьшим объёмом средств"]'::jsonb,3,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 34','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 34 указанного нормативного акта: Выбрать достижение результата с наименьшим объёмом средств.',true),
('Бюджетная политика: ситуационные задачи','У программы фиксированный бюджет 3 млрд, есть варианты добиться 70 или 95 процентов целевого результата. Что требует принцип эффективности?','["Предпочесть 70 процентов ради формального сохранения сметы","Увеличить расходы без корректировки бюджетных ассигнований","Предпочесть наилучший достижимый результат в рамках заданного объёма средств","Выбрать вариант только по числу отчётных документов"]'::jsonb,2,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 34','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 34 указанного нормативного акта: Предпочесть наилучший достижимый результат в рамках заданного объёма средств.',true),
('Бюджетная политика: ситуационные задачи','Ведомство предлагает измерять эффективность исключительно процентом освоения средств, игнорируя достигнутые результаты. В чём ошибка?','["Освоение денег всегда эквивалентно результативности","Эффективность оценивает экономность и результативность, а не одно освоение","Результативность оценивают исключительно по численности ведомства","Оценка эффективности разрешена только по окончании всех госпрограмм"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 34','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 34 указанного нормативного акта: Эффективность оценивает экономность и результативность, а не одно освоение.',true),
('Бюджетная политика: ситуационные задачи','Субъект требует направлять весь налог на прибыль строго на один проект по умолчанию, без особого основания. Какой принцип применим?','["Общее покрытие расходов бюджета без жёсткой увязки каждого налога с расходом","Обязательное закрепление каждого налога за индивидуальной статьёй","Правило обязательного возврата налогов их плательщикам","Запрет использования неналоговых доходов для расходов бюджета"]'::jsonb,0,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 35','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 35 указанного нормативного акта: Общее покрытие расходов бюджета без жёсткой увязки каждого налога с расходом.',true),
('Бюджетная политика: ситуационные задачи','Муниципалитет получил целевую субвенцию и хочет распределить её на произвольные потребности. Какая оговорка принципа общего покрытия здесь важна?','["Субвенции всегда превращаются в нецелевые налоговые поступления","Субвенции расходуются только по желанию каждого налогоплательщика","Любой целевой трансферт автоматически становится профицитом","Субвенции относятся к прямо предусмотренным исключениям из общего обезличенного покрытия"]'::jsonb,3,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 35','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 35 указанного нормативного акта: Субвенции относятся к прямо предусмотренным исключениям из общего обезличенного покрытия.',true),
('Бюджетная политика: ситуационные задачи','Жители внесли инициативные платежи на определённый объект благоустройства. Может ли бюджет учитывать целевую связь этих средств с расходами?','["Нет, такие платежи обязательно распределяются равномерно по любым статьям","Да, но только после изменения Конституции РФ","Да, инициативные платежи предусмотрены среди исключений из общего покрытия","Нет, инициативные платежи запрещены Бюджетным кодексом"]'::jsonb,2,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 35','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 35 указанного нормативного акта: Да, инициативные платежи предусмотрены среди исключений из общего покрытия.',true),
('Бюджетная политика: ситуационные задачи','Региональный бюджет утвердили, но решили вовсе не публиковать его показатели и отчёты без законного основания. Какой принцип нарушен?','["Только адресность бюджетных ассигнований","Прозрачность и открытость бюджетного процесса","Только единство кассового исполнения","Исключительно самостоятельность муниципальных налогов"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 36','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 36 указанного нормативного акта: Прозрачность и открытость бюджетного процесса.',true),
('Бюджетная политика: ситуационные задачи','Финансовый орган публикует отчёт об исполнении бюджета, но скрывает содержательные показатели без предусмотренного исключения. Что требуется?','["Соблюдать принцип прозрачности и открытости бюджетных данных","Публиковать исключительно название закона о бюджете","Отменить все публичные процедуры бюджетного процесса","Передать отчёт лишь внутренней экспертной группе"]'::jsonb,0,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 36','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 36 указанного нормативного акта: Соблюдать принцип прозрачности и открытости бюджетных данных.',true),
('Бюджетная политика: ситуационные задачи','При составлении доходов бюджета ведомство использует заведомо завышенную налоговую базу вместо реалистичного прогноза. Какой принцип поставлен под угрозу?','["Подведомственность расходов бюджетов","Правило назначения федеральных министров","Правило об обязательной межведомственной закупке","Достоверность бюджета и реалистичность расчёта доходов"]'::jsonb,3,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 37','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 37 указанного нормативного акта: Достоверность бюджета и реалистичность расчёта доходов.',true),
('Бюджетная политика: ситуационные задачи','В региональном финансовом плане ожидаемые доходы не подкреплены прогнозом социально-экономического развития, хотя оценка доступна. Что необходимо обеспечить?','["Увеличение расходов пропорционально числу депутатов","Введение нового налога вне Налогового кодекса","Надёжность показателей прогноза и реалистичность расчёта бюджета","Обязательное исключение межбюджетных трансфертов"]'::jsonb,2,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 37','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 37 указанного нормативного акта: Надёжность показателей прогноза и реалистичность расчёта бюджета.',true),
('Бюджетная политика: ситуационные задачи','Главный распорядитель получил средства на школьное строительство и направил их на не предусмотренное целями рекламное мероприятие. Что нарушено?','["Принцип равенства бюджетных прав субъектов","Адресность и целевое назначение бюджетных средств","Самостоятельность бюджета как право тратить без ограничений","Общее покрытие как разрешение менять назначение любой субсидии"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 38','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 38 указанного нормативного акта: Адресность и целевое назначение бюджетных средств.',true),
('Бюджетная политика: ситуационные задачи','Ведомство хочет выделить средства без указания получателя и конкретной цели ассигнования. Какой принцип бюджета требует уточнения?','["Адресность бюджетных средств и определённость цели использования","Принцип исключительно приватного софинансирования","Принцип выбора получателя по политическому статусу","Правило об обязательной передаче всех ассигнований региональным партиям"]'::jsonb,0,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 38','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 38 указанного нормативного акта: Адресность бюджетных средств и определённость цели использования.',true),
('Бюджетная политика: ситуационные задачи','Региональный орган хочет проводить все кассовые выплаты бюджета через множество неувязанных счетов ведомств вне установленной системы. Какой принцип следует учитывать?','["Принцип обязательного ведомственного наличного расчёта","Обязательность самостоятельного эмиссионного счёта каждого учреждения","Право учреждений самостоятельно создавать новый региональный бюджет","Единство кассы и установленный порядок кассовых поступлений и выплат"]'::jsonb,3,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 38.2','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 38.2 указанного нормативного акта: Единство кассы и установленный порядок кассовых поступлений и выплат.',true),
('Бюджетная политика: ситуационные задачи','Региональному органу предлагают установить расходное обязательство без определения, бюджет какого уровня его финансирует. Какое ограничение действует?','["Допускается при наличии обещания будущих пожертвований","Допускается, если обязательство включено в политическую программу","Нельзя устанавливать расходное обязательство без определения надлежащего бюджета-источника","Допускается, если источником назвать консолидированный бюджет без разграничения"]'::jsonb,2,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 31','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 31 указанного нормативного акта: Нельзя устанавливать расходное обязательство без определения надлежащего бюджета-источника.',true),
('Бюджетная политика: ситуационные задачи','Две программы требуют одинаковых ассигнований, но одна имеет более высокий измеримый эффект. На что ориентирует БК?','["На выбор программы с самым длительным сроком оформления","На достижение наилучшего результата при данном объёме бюджетных средств","На равное расходование средств независимо от эффекта","На отказ от использования индикаторов эффективности"]'::jsonb,1,'Бюджетный кодекс Российской Федерации, № 145-ФЗ','статья 34','https://www.consultant.ru/document/cons_doc_LAW_19702/91e122f1a82147f37d5fffa2b196877460c75790/','Правовое решение вытекает из статьи 34 указанного нормативного акта: На достижение наилучшего результата при данном объёме бюджетных средств.',true),
('Налоги: экономические ограничения и процедуры','Регион вводит налог исключительно для компаний с иностранными учредителями, не предусмотрев объективной налоговой базы. Какой принцип нарушен?','["Недискриминация и требование экономического основания налогообложения","Обязательное предпочтение национальных компаний как налоговый принцип","Право каждого субъекта назначать ставки по гражданству учредителей","Запрет применять единые налоговые правила к разным компаниям"]'::jsonb,0,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 3 указанного нормативного акта: Недискриминация и требование экономического основания налогообложения.',true),
('Налоги: экономические ограничения и процедуры','Проект местного налога создаёт платный барьер перемещению товара между соседними субъектами. Какое ограничение действует?','["Разрешение ограничивать перемещение товаров муниципальным налогом","Обязательное согласование такого платежа только с территориальной комиссией","Налог допускается, если собранные средства расходуются на дороги","Недопустимость налоговых препятствий единому экономическому пространству"]'::jsonb,3,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 3 указанного нормативного акта: Недопустимость налоговых препятствий единому экономическому пространству.',true),
('Налоги: экономические ограничения и процедуры','В налоговом законе невозможно однозначно определить размер обязанности даже после применения способов толкования. В чью пользу разрешаются неустранимые неясности?','["В пользу налогового органа при любом споре","В пользу бюджета с наибольшим дефицитом","В пользу налогоплательщика или иного указанного в НК обязанного лица","В пользу любого получателя бюджетной субсидии"]'::jsonb,2,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 3 указанного нормативного акта: В пользу налогоплательщика или иного указанного в НК обязанного лица.',true),
('Налоги: экономические ограничения и процедуры','Законодатель вводит налог без экономической связи с объектом и реальной платёжеспособностью лиц. Какое начало НК РФ нарушается?','["Обязательное требование направлять налог исключительно в региональный фонд","Необходимость экономического основания и запрет произвольного налога","Правило о платности всех государственных услуг","Обязанность налогоплательщика самому установить налоговую базу"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 3 указанного нормативного акта: Необходимость экономического основания и запрет произвольного налога.',true),
('Налоги: экономические ограничения и процедуры','Для организаций государственной формы собственности установили льготу только по критерию формы собственности. Какое правило применимо?','["Не допускается дифференцировать налоговые льготы только по форме собственности","Такое различие всегда допускается без экономического обоснования","Любое предприятие с госучастием освобождено от налогов","Региональный парламент вправе заменить НК РФ специальным решением"]'::jsonb,0,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 3 указанного нормативного акта: Не допускается дифференцировать налоговые льготы только по форме собственности.',true),
('Налоги: экономические ограничения и процедуры','Налоговый закон описывает объект и ставку, но не позволяет понять, когда именно гражданин обязан заплатить. Какой критерий нарушен?','["Достаточность любых двух элементов налога","Право налоговой инспекции устанавливать элементы устно","Обязанность гражданина рассчитать сроки самостоятельно без закона","Обязанность законодателя сформулировать элементы так, чтобы плательщик знал срок и порядок уплаты"]'::jsonb,3,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 3 указанного нормативного акта: Обязанность законодателя сформулировать элементы так, чтобы плательщик знал срок и порядок уплаты.',true),
('Налоги: экономические ограничения и процедуры','Парламент предлагает считать новый налог установленным при указании налоговой ставки, но не определяет налогоплательщика. Что необходимо?','["Оставить налог без плательщиков, указав лишь цель его поступлений","Утвердить ставку постановлением муниципального старосты","Определить плательщиков и обязательные элементы налогообложения","Включить налог в государственную программу без указания базы"]'::jsonb,2,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 17 указанного нормативного акта: Определить плательщиков и обязательные элементы налогообложения.',true),
('Налоги: экономические ограничения и процедуры','Налог введён, но законодатель не определил порядок исчисления. Достаточно ли фиксирования базы и ставки?','["Да, порядок исчисления всегда выбирает налоговый агент","Нет, порядок исчисления является обязательным элементом","Да, если налог зачисляется в федеральный бюджет","Да, при утверждении регионального финансового плана"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 17 указанного нормативного акта: Нет, порядок исчисления является обязательным элементом.',true),
('Налоги: экономические ограничения и процедуры','Для налога разового характера не указан налоговый период. Как трактует это НК РФ?','["Для разовых налогов предусмотрено исключение из общего требования налогового периода","Любой налог без периода автоматически становится штрафом","Разовый налог запрещён при любых обстоятельствах","Период обязан составлять ровно год для всех налогов"]'::jsonb,0,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 17 указанного нормативного акта: Для разовых налогов предусмотрено исключение из общего требования налогового периода.',true),
('Налоги: экономические ограничения и процедуры','Федеральный орган предлагает заменить установленный НК РФ налог обязательным ведомственным сбором с теми же признаками без предусмотренного порядка. Какое правило действует?','["Ведомство вправе вводить любые обязательные платежи приказом","Платежи вне НК допускаются при одобрении муниципалитета","Платежи с признаками налога автоматически считаются добровольными","Нельзя взимать платежи с признаками налогов или сборов вне предусмотренного НК порядка"]'::jsonb,3,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 3 указанного нормативного акта: Нельзя взимать платежи с признаками налогов или сборов вне предусмотренного НК порядка.',true),
('Налоги: экономические ограничения и процедуры','Налоговое обязательство одинаковых по экономическому положению лиц различается лишь по их религии. Какой критерий нарушен?','["Принцип специальной поддержки конкретной конфессии за счёт налогов","Правило свободного установления региональных налогов по вероисповеданию","Запрет дискриминации по религиозному и сходным признакам","Принцип усмотрения налогового органа при выборе плательщика"]'::jsonb,2,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 3 указанного нормативного акта: Запрет дискриминации по религиозному и сходным признакам.',true),
('Налоги: экономические ограничения и процедуры','Министерство обещает налоговую льготу, не установив её в законодательстве, и объявляет её обязательным элементом каждого налога. Что неточно?','["Льготы обязательно существуют у любого федерального налога","Льготы могут предусматриваться при установлении налога, но не являются универсально обязательным элементом","Любая ведомственная публикация сама устанавливает налоговую льготу","Льготы запрещено предусматривать в налоговом законодательстве"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая), № 146-ФЗ','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/d03926665a6af79635a902fe666ce607ad1cdab0/','Правовое решение вытекает из статьи 17 указанного нормативного акта: Льготы могут предусматриваться при установлении налога, но не являются универсально обязательным элементом.',true),
('Антимонопольное регулирование рынков','Доминирующая электросетевая организация подключает новых клиентов только при покупке посторонних консультационных услуг без обоснования. Что следует оценить?','["Навязывание не относящихся к предмету договора невыгодных условий","Разрешённую безусловно экономию расходов монополиста","Автоматическое право любой монополии на связанные продажи","Исключительно нарушение порядка публичных слушаний"]'::jsonb,0,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Правовое решение вытекает из статьи 10 указанного нормативного акта: Навязывание не относящихся к предмету договора невыгодных условий.',true),
('Антимонопольное регулирование рынков','Доминирующий поставщик сохраняет возможность прибыльно производить товар, спрос высок, но искусственно прекращает выпуск. Какова правовая квалификация?','["Законное прекращение выпуска при любом объёме спроса","Автоматическое требование признать поставщика банкротом","Вопрос только о регистрации торгового знака","Возможное злоупотребление доминированием при необоснованном сокращении производства"]'::jsonb,3,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Правовое решение вытекает из статьи 10 указанного нормативного акта: Возможное злоупотребление доминированием при необоснованном сокращении производства.',true),
('Антимонопольное регулирование рынков','Доминирующая компания отказывает отдельному покупателю в контракте при наличии мощности и отсутствии объективных оснований. Что наиболее обоснованно?','["Отказ всегда допустим без объяснений","Проверять только превышение бюджетных ассигнований","Проверить необоснованный отказ от заключения договора как злоупотребление","Признать отказ обоснованным из-за одного лишь доминирования"]'::jsonb,2,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Правовое решение вытекает из статьи 10 указанного нормативного акта: Проверить необоснованный отказ от заключения договора как злоупотребление.',true),
('Антимонопольное регулирование рынков','Монополист продаёт одинаковый товар сопоставимым покупателям по резко разным ценам без экономической причины. Какая норма релевантна?','["Автоматическое право монополиста на любые тарифные различия","Запрет необоснованного установления различных цен на один товар","Принцип обязательного равенства всех местных бюджетов","Правило о проведении закупок с единственным поставщиком"]'::jsonb,1,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Правовое решение вытекает из статьи 10 указанного нормативного акта: Запрет необоснованного установления различных цен на один товар.',true),
('Антимонопольное регулирование рынков','Доминирующий перевозчик создаёт новые технические барьеры для выхода конкурирующей компании на рынок без обоснования. Какая проблема возникает?','["Создание препятствий доступу на товарный рынок","Только нарушение сроков проведения референдума","Обязательное подтверждение федеральной стратегии","Допустимое исключительное право на любые технические ограничения"]'::jsonb,0,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Правовое решение вытекает из статьи 10 указанного нормативного акта: Создание препятствий доступу на товарный рынок.',true),
('Антимонопольное регулирование рынков','Доминирующая компания сократила поставки лишь для повышения рыночной цены, не объяснив экономических причин. Что проверяет антимонопольный орган?','["Законность обращения товара исключительно по ведомственной лицензии","Обязанность конкурентов установить ту же цену","Только корректность размера госпошлины","Злоупотребление доминированием через изъятие товара из обращения"]'::jsonb,3,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 10','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Правовое решение вытекает из статьи 10 указанного нормативного акта: Злоупотребление доминированием через изъятие товара из обращения.',true),
('Антимонопольное регулирование рынков','Два конкурирующих производителя договорились поддерживать минимальную отпускную цену. Как квалифицируется соглашение?','["Обычный межбюджетный трансферт","Договор, автоматически разрешённый при отсутствии государственного участия","Запрещённое картельное соглашение о цене при наличии условий закона","Обязательный механизм государственного регулирования цен"]'::jsonb,2,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Правовое решение вытекает из статьи 11 указанного нормативного акта: Запрещённое картельное соглашение о цене при наличии условий закона.',true),
('Антимонопольное регулирование рынков','Конкурирующие поставщики заранее договорились, кто победит на муниципальном аукционе. Что нарушено?','["Правило об обязательном участии в заседании Правительства","Запрет картелей, приводящих или способных привести к поддержанию цен на торгах","Порядок утверждения стратегии социально-экономического развития","Исключительно правило опубликования муниципального бюджета"]'::jsonb,1,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Правовое решение вытекает из статьи 11 указанного нормативного акта: Запрет картелей, приводящих или способных привести к поддержанию цен на торгах.',true),
('Антимонопольное регулирование рынков','Несколько конкурентов поделили клиентов по территориям, пообещав не выходить на рынки друг друга. Как оценить?','["Раздел рынка между конкурентами может образовывать запрещённый картель","Раздел территории обязателен для любого конкурентного рынка","Раздел рынка допустим без ограничений при устном соглашении","Это является исключительно вопросом муниципального землепользования"]'::jsonb,0,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Правовое решение вытекает из статьи 11 указанного нормативного акта: Раздел рынка между конкурентами может образовывать запрещённый картель.',true),
('Антимонопольное регулирование рынков','Конкурирующие компании договорились не заключать договоры с конкретной группой покупателей без законного основания. Какой риск возникает?','["Обязательное проявление добросовестной конкуренции","Исключительно нарушение закона о персональных данных","Автоматическое право поставщиков отказываться от любого договора","Запрещённое соглашение об экономически необоснованном отказе от контрактов"]'::jsonb,3,'Федеральный закон от 26.07.2006 № 135-ФЗ «О защите конкуренции»','статья 11','https://www.consultant.ru/document/cons_doc_LAW_61763/851f7a5f6d99da11639600f4c686a2949ab23feb/','Правовое решение вытекает из статьи 11 указанного нормативного акта: Запрещённое соглашение об экономически необоснованном отказе от контрактов.',true),
('Государственные закупки и конкуренция','Заказчик ввёл требования к участнику закупки, намеренно ограничивающие круг поставщиков без связи с предметом. Какой принцип затронут?','["Право заказчика устранять конкуренцию ради сокращения числа заявок","Правило обязательной закупки у единственного поставщика","Обеспечение конкуренции и создание равных условий участия в закупке","Принцип скрытия информации о критериях отбора"]'::jsonb,2,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_144624/0c4ec341947f98654432292ddfd7066e3200d7fd/','Правовое решение вытекает из статьи 8 указанного нормативного акта: Обеспечение конкуренции и создание равных условий участия в закупке.',true),
('Государственные закупки и конкуренция','К участию в закупке допущены только поставщики из района заказчика без законного основания. Что следует проверить?','["Наличие свободной конкуренции как следствие местной регистрации","Необоснованное ограничение числа участников закупки","Обязанность отменить все критерии качества","Право муниципалитета вводить произвольную территориальную квоту"]'::jsonb,1,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_144624/0c4ec341947f98654432292ddfd7066e3200d7fd/','Правовое решение вытекает из статьи 8 указанного нормативного акта: Необоснованное ограничение числа участников закупки.',true),
('Государственные закупки и конкуренция','Учреждение выбирает между конкурентной процедурой и единственным поставщиком. Каково общее правило?','["Применять способы, предусмотренные 44-ФЗ; единственный поставщик допустим лишь в случаях закона","Всегда выбирать единственного поставщика при любой срочности","Применять только закрытые конкурентные способы","Заменять закупку соглашением между местными депутатами"]'::jsonb,0,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 24','https://www.consultant.ru/document/cons_doc_LAW_144624/0c4ec341947f98654432292ddfd7066e3200d7fd/','Правовое решение вытекает из статьи 24 указанного нормативного акта: Применять способы, предусмотренные 44-ФЗ; единственный поставщик допустим лишь в случаях закона.',true),
('Государственные закупки и конкуренция','Заказчик размещает открытое извещение о закупке, доступное неопределённому кругу лиц в ЕИС. Какой способ по своему характеру используется?','["Закрытая процедура с ограниченным кругом приглашённых","Обязательная закупка исключительно у единственного поставщика","Внутренний отбор сотрудников учреждения","Открытая конкурентная процедура при соблюдении остальных требований"]'::jsonb,3,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 24','https://www.consultant.ru/document/cons_doc_LAW_144624/0c4ec341947f98654432292ddfd7066e3200d7fd/','Правовое решение вытекает из статьи 24 указанного нормативного акта: Открытая конкурентная процедура при соблюдении остальных требований.',true),
('Государственные закупки и конкуренция','Проект контракта после определения победителя произвольно меняет существенные условия предложения и извещения, хотя исключение законом не предусмотрено. Как оценить?','["После торгов заказчик вправе произвольно менять предмет контракта","Контракт может противоречить извещению по решению главного бухгалтера","Контракт должен соответствовать условиям закупки и заявке в пределах закона","Любые условия устанавливает только победитель без ограничений"]'::jsonb,2,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 34','https://www.consultant.ru/document/cons_doc_LAW_144624/0c4ec341947f98654432292ddfd7066e3200d7fd/','Правовое решение вытекает из статьи 34 указанного нормативного акта: Контракт должен соответствовать условиям закупки и заявке в пределах закона.',true),
('Государственные закупки и конкуренция','Муниципальный заказчик хочет приобрести услугу из сферы естественной монополии и рассматривает единственного поставщика. Какое основание применять?','["Общее освобождение от 44-ФЗ для всех муниципальных закупок","Предусмотренное пунктом 1 части 1 статьи 93 основание для соответствующей сферы","Автоматическое право заключать любые договоры с единственным поставщиком","Исключительно процедуру регионального референдума"]'::jsonb,1,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 93','https://www.consultant.ru/document/cons_doc_LAW_144624/0c4ec341947f98654432292ddfd7066e3200d7fd/','Правовое решение вытекает из статьи 93 указанного нормативного акта: Предусмотренное пунктом 1 части 1 статьи 93 основание для соответствующей сферы.',true),
('Государственные закупки и конкуренция','Контрактный управляющий объясняет закупку у единственного поставщика тем, что конкурс требует времени, но специального основания статьи 93 нет. Каков вывод?','["Одного удобства недостаточно: нужно законное основание закупки у единственного поставщика","Удобство заказчика заменяет предусмотренные законом основания","Закупка у единственного поставщика допустима для любой услуги без ограничений","Заявка одного поставщика всегда устраняет обязанность соблюдать 44-ФЗ"]'::jsonb,0,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 93','https://www.consultant.ru/document/cons_doc_LAW_144624/0c4ec341947f98654432292ddfd7066e3200d7fd/','Правовое решение вытекает из статьи 93 указанного нормативного акта: Одного удобства недостаточно: нужно законное основание закупки у единственного поставщика.',true),
('Государственные закупки и конкуренция','Чиновник предлагает не размещать информацию об обычной открытой закупке, чтобы выбрать знакомого исполнителя. Какое требование затронуто?','["Обязанность публиковать только заключённый контракт","Разрешение ограничивать доступ по личному знакомству","Обязанность согласовывать победителя с депутатами региона","Конкурентные равные условия и законное информирование потенциальных участников"]'::jsonb,3,'Федеральный закон от 05.04.2013 № 44-ФЗ «О контрактной системе»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_144624/0c4ec341947f98654432292ddfd7066e3200d7fd/','Правовое решение вытекает из статьи 8 указанного нормативного акта: Конкурентные равные условия и законное информирование потенциальных участников.',true),
('Конституционные основы экономики','Субъект предлагает запретить перемещение продукции из других регионов ради поддержки своих предприятий. Какой конституционный принцип затронут?','["Право субъекта устанавливать собственную таможенную границу","Свобода региона принимать федеральные экономические законы","Единство экономического пространства и свободное перемещение товаров","Право местного органа проводить денежную эмиссию"]'::jsonb,2,'Конституция Российской Федерации','статья 8','https://minjust.gov.ru/ru/documents/8011/','Правовое решение вытекает из статьи 8 указанного нормативного акта: Единство экономического пространства и свободное перемещение товаров.',true),
('Конституционные основы экономики','Региональное правительство хочет самостоятельно осуществлять эмиссию денежных знаков. Чья компетенция затрагивается?','["Эмиссия относится исключительно к местным налогам","Денежная эмиссия находится в ведении Российской Федерации","Эмиссия самостоятельно регулируется законом каждого субъекта","Эмиссия относится только к совместному ведению муниципалитетов"]'::jsonb,1,'Конституция Российской Федерации','статья 71','https://minjust.gov.ru/ru/documents/8011/','Правовое решение вытекает из статьи 71 указанного нормативного акта: Денежная эмиссия находится в ведении Российской Федерации.',true),
('Конституционные основы экономики','Губернатор предлагает ввести региональную валюту для расчётов по государственным программам. Что следует из Конституции?','["Денежная единица РФ — рубль, эмиссия других денег не допускается","Региональная валюта допустима при положительном бюджете","Регион вправе эмитировать деньги без согласия Банка России","Валюта субъекта вводится региональным уставом"]'::jsonb,0,'Конституция Российской Федерации','статья 75','https://minjust.gov.ru/ru/documents/8011/','Правовое решение вытекает из статьи 75 указанного нормативного акта: Денежная единица РФ — рубль, эмиссия других денег не допускается.',true),
('Конституционные основы экономики','Парламент предлагает возложить проведение денежной эмиссии на федеральное казначейство вместо Банка России. Каков конституционный режим?','["Эмиссию осуществляет любой федеральный финансовый орган","Эмиссия относится к полномочиям Совета Федерации","Эмиссию выполняет исключительно Правительство РФ","Денежная эмиссия осуществляется исключительно Центральным банком РФ"]'::jsonb,3,'Конституция Российской Федерации','статья 75','https://minjust.gov.ru/ru/documents/8011/','Правовое решение вытекает из статьи 75 указанного нормативного акта: Денежная эмиссия осуществляется исключительно Центральным банком РФ.',true),
('Конституционные основы экономики','Федеральное ведомство предлагает подчинить главную функцию защиты устойчивости рубля собственному ведомственному распоряжению. Какой конституционный принцип?','["Защита устойчивости рубля является исключительной обязанностью субъекта РФ","Решения Банка России всегда утверждаются муниципальными собраниями","Банк России осуществляет защиту устойчивости рубля независимо от других органов государственной власти","Банк России не имеет самостоятельных конституционных функций"]'::jsonb,2,'Конституция Российской Федерации','статья 75','https://minjust.gov.ru/ru/documents/8011/','Правовое решение вытекает из статьи 75 указанного нормативного акта: Банк России осуществляет защиту устойчивости рубля независимо от других органов государственной власти.',true),
('Конституционные основы экономики','Региональная дума предлагает своим законом установить общие основы валютного и таможенного регулирования страны. Как разграничена компетенция?','["К исключительному ведению всех муниципалитетов","Валютное и таможенное регулирование относится к ведению Российской Федерации","К ведению субъектов без федерального регулирования","К полномочиям только представительных органов городских округов"]'::jsonb,1,'Конституция Российской Федерации','статья 71','https://minjust.gov.ru/ru/documents/8011/','Правовое решение вытекает из статьи 71 указанного нормативного акта: Валютное и таможенное регулирование относится к ведению Российской Федерации.',true),
('Стратегические решения в экономике','Министерство разработало экономическую стратегию без оценки внутренних и внешних ограничений развития. Какая задача стратегического планирования упущена?','["Определение условий, ограничений, рисков и возможностей развития","Обязательное утверждение всех целей судом","Только проведение муниципального референдума","Назначение региональных министров федеральным органом"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Правовое решение вытекает из статьи 8 указанного нормативного акта: Определение условий, ограничений, рисков и возможностей развития.',true),
('Стратегические решения в экономике','Правительство подготовило стратегию, но не согласовало показатели с бюджетной политикой. Какая задача 172-ФЗ под угрозой?','["Обязательное объединение всех бюджетов в один счёт муниципалитета","Передача бюджетных полномочий из Госдумы в федеральные ведомства","Замена стратегии финансовой отчётностью без целей","Координация стратегического управления и мер бюджетной политики"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Правовое решение вытекает из статьи 8 указанного нормативного акта: Координация стратегического управления и мер бюджетной политики.',true),
('Стратегические решения в экономике','Регион выбрал способы достижения цели, расходующие вдвое больше ресурсов при равном результате, без анализа альтернатив. Что требует закон?','["Выбирать самый затратный способ ради полного освоения бюджета","Не учитывать ресурсные ограничения до исполнения программы","Выбирать способы, обеспечивающие наибольшую эффективность использования ресурсов","Считать расходы главным показателем качества стратегии"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Правовое решение вытекает из статьи 8 указанного нормативного акта: Выбирать способы, обеспечивающие наибольшую эффективность использования ресурсов.',true),
('Стратегические решения в экономике','Два ведомства подготовили несовместимые региональные и федеральные экономические приоритеты. Какая задача стратегического планирования важна?','["Замена всех программ одним ведомственным указом","Координация государственного и муниципального стратегического управления","Проведение отдельных выборов по каждому стратегическому показателю","Планирование только на муниципальном уровне"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Правовое решение вытекает из статьи 8 указанного нормативного акта: Координация государственного и муниципального стратегического управления.',true),
('Стратегические решения в экономике','Стратегия утверждена, но министерство не оценило возможные сценарии угроз национальной безопасности. Какая задача затронута?','["Определение внутренних и внешних условий, ограничений и рисков развития и безопасности","Только кадровое назначение руководителей территориальных органов","Обязательное снижение налогов в течение первого года","Запрет использования прогнозов при экономическом планировании"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Правовое решение вытекает из статьи 8 указанного нормативного акта: Определение внутренних и внешних условий, ограничений и рисков развития и безопасности.',true),
('Стратегические решения в экономике','При выборе госпрограммы ведомство не сопоставило сроки, затраты и ожидаемый результат. Какой подход соответствует задачам закона?','["Выбор наибольшей по стоимости программы без учёта результата","Отсутствие необходимости сопоставлять варианты стратегических действий","Определение решения исключительно по числу ведомств-исполнителей","Выбор путей достижения целей с наибольшей эффективностью необходимых ресурсов"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ «О стратегическом планировании»','статья 8','https://www.consultant.ru/document/cons_doc_LAW_164841/92c5eb34d45a002d86abdd9feeeb747d1bd8d431/','Правовое решение вытекает из статьи 8 указанного нормативного акта: Выбор путей достижения целей с наибольшей эффективностью необходимых ресурсов.',true)
